/* The comparison report of the external sample check, as markdown for
 * reading and CSV for a spreadsheet (docs/external-check.md, "What comes
 * back"). */
import { writeCsv } from "./csv";
import { showValue, type CheckRow, type DecisiveLine } from "./runner";

export interface ReportMeta {
  title: string;
  volume: string;
  commit: string;
  date: string;
  /** Persons' labels by case. */
  persons: Record<string, Record<string, string>>;
  /** Notes about each case (a date of birth set from an age). */
  caseNotes: Record<string, string[]>;
}

const esc = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");

function who(p: string | null, persons: Record<string, string>): string {
  return p ? persons[p] ?? `Person ${p.slice(1)}` : "the household";
}

export function decisiveText(l: DecisiveLine, persons: Record<string, string>): string {
  const ref = [l.identifier, l.id].filter(Boolean).join(", ");
  const scope = [l.person ? who(l.person, persons) : "", l.month ?? ""].filter(Boolean).join(", ");
  const kind = l.kind === "derived" ? "rule" : l.kind === "parameter" ? "figure" : "fact";
  return `${l.name} (${kind} ${ref}${scope ? "; " + scope : ""}) = ${showValue(l.value, persons)}`;
}

/** The comparison report as markdown. */
export function reportMarkdown(rows: readonly CheckRow[], meta: ReportMeta): string {
  const out: string[] = [];
  const cases = [...new Set(rows.map((r) => r.case))];
  const differ = rows.filter((r) => r.status === "differ");
  const cannot = differ.filter((r) => r.engine === null).length;
  out.push(`# External sample check: ${meta.title}`, "");
  out.push(`Volume \`${meta.volume}\`, codex commit \`${meta.commit}\`, run ${meta.date}. Generated by \`npm run external:check\`; see docs/external-check.md.`, "");
  out.push(`**${cases.length} case${cases.length === 1 ? "" : "s"}, ${rows.length} expected answer${rows.length === 1 ? "" : "s"}: ${rows.length - differ.length} match, ${differ.length} differ${cannot ? ` (the engine cannot determine ${cannot} of them)` : ""}.**`, "");
  const programs = [...new Set(rows.map((r) => r.programLabel))];
  out.push("| Program | Answers | Match | Differ |", "|---|---:|---:|---:|");
  for (const p of programs) {
    const rs = rows.filter((r) => r.programLabel === p);
    const d = rs.filter((r) => r.status === "differ").length;
    out.push(`| ${esc(p)} | ${rs.length} | ${rs.length - d} | ${d} |`);
  }
  if (differ.length) {
    const cats = new Map<string, number>();
    for (const r of differ) cats.set(r.hints[0]?.category ?? "", (cats.get(r.hints[0]?.category ?? "") ?? 0) + 1);
    out.push("", "First triage hints of the differences: " + [...cats].map(([c, n]) => `${c} ${n}`).join(", ") + ".");
  }
  out.push("", "## Results by case", "");
  for (const c of cases) {
    const rs = rows.filter((r) => r.case === c);
    const persons = meta.persons[c] ?? {};
    out.push(`### ${esc(c)}: ${esc(rs[0].title)}`, "");
    for (const n of meta.caseNotes[c] ?? []) out.push(`- ${n}`);
    if ((meta.caseNotes[c] ?? []).length) out.push("");
    out.push("| Person | Program | Result | Month | Expected | Engine | | Source |", "|---|---|---|---|---|---|---|---|");
    for (const r of rs) {
      out.push(`| ${esc(r.personLabel)} | ${esc(r.programLabel)} | ${esc(r.resultLabel)} | ${r.month ?? ""} | ${esc(showValue(r.expected, persons))} | ${esc(showValue(r.engine, persons))} | ${r.status === "match" ? "match" : "**differ**"} | ${esc(r.source)} |`);
    }
    out.push("");
  }
  out.push("## Differences", "");
  if (!differ.length) out.push("None: every expected answer matches the engine's.", "");
  for (const r of differ) {
    const persons = meta.persons[r.case] ?? {};
    out.push(`### ${esc(r.case)}, ${esc(r.personLabel)}, ${esc(r.resultLabel)}${r.month ? `, ${r.month}` : ""}`, "");
    out.push(`- **Expected:** ${esc(showValue(r.expected, persons))}${r.source ? ` (${esc(r.source)})` : ""}${r.notes ? `. Notes: ${esc(r.notes)}` : ""}`);
    out.push(`- **Engine:** ${esc(showValue(r.engine, persons))}${r.error ? ` (error: ${esc(r.error)})` : ""}`);
    out.push(`- **First triage hint:** ${r.hints[0] ? `${r.hints[0].category}. ${esc(r.hints[0].text)}` : ""}`);
    for (const h of r.hints.slice(1)) out.push(`- Also: ${h.category}. ${esc(h.text)}`);
    if (r.missing.length) {
      out.push(`- **Missing facts** (${r.missing.length}):`);
      for (const m of r.missing) out.push(`  - ${esc(m.name)} (\`${m.identifier}\`${m.id ? ", " + m.id : ""}) for ${who(m.person, persons)}${m.month ? " in " + m.month : ""}`);
    }
    if (r.decisive.length) {
      out.push("- **Decisive rules** (what decided the engine's answer, then what decided that):");
      for (const l of r.decisive) out.push(`${"  ".repeat(l.depth + 1)}- ${esc(decisiveText(l, persons))}`);
      if (r.moreDecisive) out.push(`  - ... and ${r.moreDecisive} more`);
    }
    out.push("");
  }
  return out.join("\n");
}

export const REPORT_CSV_HEADERS = [
  "case", "person", "program", "result", "result identifier", "month", "expected answer", "engine answer",
  "match or differ", "source of the expected answer", "notes", "first triage hint", "other hints",
  "missing facts", "decisive rules",
] as const;

/** The comparison report as CSV, one row per expected answer. */
export function reportCsv(rows: readonly CheckRow[], meta: ReportMeta): string {
  return writeCsv(REPORT_CSV_HEADERS, rows.map((r) => {
    const persons = meta.persons[r.case] ?? {};
    return [
      r.case, r.personLabel, r.programLabel, r.resultLabel, r.identifier, r.month ?? "",
      showValue(r.expected, persons), showValue(r.engine, persons), r.status, r.source, r.notes,
      r.hints[0] ? `${r.hints[0].category}: ${r.hints[0].text}` : "",
      r.hints.slice(1).map((h) => `${h.category}: ${h.text}`).join(" | "),
      r.missing.map((m) => `${m.name} (${m.identifier}) for ${who(m.person, persons)}${m.month ? " in " + m.month : ""}`).join(" | "),
      r.decisive.map((l) => `${"> ".repeat(l.depth)}${decisiveText(l, persons)}`).join(" | ") + (r.moreDecisive ? ` | ... and ${r.moreDecisive} more` : ""),
    ];
  }));
}
